We can create a Queue class using two stacks. We'll use one stack for enqueue operation and another stack for dequeue operation. When a new item is added to the queue, it's pushed to the enqueue stack. When an item is removed (dequeued) from the queue, the items are popped from the enqueue stack and pushed to the dequeue stack. When we pop an item from the dequeue stack, it's the front of the queue. Here is the implementation:

```
class Stack:
    def __init__(self):
        self.stack = []

    def push(self, item):
        self.stack.append(item)

    def pop(self):
        if not self.is_empty():
            return self.stack.pop()
        return None

    def is_empty(self):
        return len(self.stack) == 0

    def size(self):
        return len(self.stack)


class Queue:
    def __init__(self):
        self.enQueue = Stack()
        self.deQueue = Stack()

    def enQueue(self, item):
        self.enQueue.push(item)

    def deQueue(self):
        if self.deQueue.is_empty():
            while not self.enQueue.is_empty():
                self.deQueue.push(self.enQueue.pop())
        if self.deQueue.size() > 0:
            return self.deQueue.pop()
        return None

    def size(self):
        return self.enQueue.size() + self.deQueue.size()

    def is_empty(self):
        return self.enQueue.is_empty() and self.deQueue.is_empty()


# Example usage:
queue = Queue()
queue.enQueue(1)
queue.enQueue(2)
queue.enQueue(3)

print(queue.deQueue())  # prints 1
print(queue.deQueue())  # prints 2
print(queue.deQueue())  # prints 3
print(queue.deQueue())  # prints None
```

In the code above, the `Queue` class uses `Stack` for `enQueue` and `deQueue` operations. The `enQueue` stack stores the new items that are pushed to the back of the queue. The `deQueue` stack is used to store the items that are removed from the front of the queue.<|start_header_id|>assistant<|end_header_id|>

