Voici un exemple de code en C# qui crée un serveur HTTP à l'aide de `HttpListener` et affiche la page "hello" sur le port 8080 :
```csharp
using System;
using System.Net;
using System.IO;

class HelloServer
{
    static void Main(string[] args)
    {
        // Créer un nouvel objet HttpListener
        HttpListener listener = new HttpListener();

        // Configurer l'écoute sur le port 8080
        listener.Prefixes.Add("http://localhost:8080/");

        // Démarrer l'écoute
        listener.Start();

        Console.WriteLine("Server started. Listening on port 8080...");

        // Boucle d'écoute
        while (true)
        {
            // Attendre une requête HTTP
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête
            string response = "Hello World!";
            context.Response.StatusCode = 200;
            context.Response.StatusDescription = "OK";
            byte[] buffer = System.Text.Encoding.UTF8.GetBytes(response);
            context.Response.OutputStream.Write(buffer, 0, buffer.Length);
            context.Response.OutputStream.Close();
        }
    }
}
```
